package terraform.guardrails_test

import rego.v1
import data.terraform.guardrails

sg(cidr) := {"resource_changes": [{
	"address": "aws_security_group.t",
	"type": "aws_security_group",
	"change": {"after": {"ingress": [{"from_port": 22, "to_port": 22, "cidr_blocks": [cidr]}]}},
}]}

test_ssh_from_internet_denied if {
	count(guardrails.deny) == 1 with input as sg("0.0.0.0/0")
}

test_ssh_from_vpc_allowed if {
	count(guardrails.deny) == 0 with input as sg("10.0.0.0/16")
}

import "tfplan/v2" as tfplan

# security groups this run creates or updates that open SSH to the internet
ssh_open = filter tfplan.resource_changes as _, rc {
	rc.type is "aws_security_group" and
	(rc.change.actions contains "create" or rc.change.actions contains "update") and
	any rc.change.after.ingress as rule {
		rule.from_port <= 22 and rule.to_port >= 22 and
		rule.cidr_blocks contains "0.0.0.0/0"
	}
}

main = rule {
	ssh_open is empty
}

package terraform.guardrails

import rego.v1

# Exceptions are reviewed code too: an owner, a reason, an end date
exceptions := {
	"aws_security_group.bastion": {"owner": "netops", "reason": "INC-2291 vendor access", "expires": "2026-12-31"},
	"aws_security_group.legacy": {"owner": "shop-team", "reason": "migration", "expires": "2026-06-30"},
}

# input.today is passed in by the pipeline (YYYY-MM-DD), which keeps
# the policy deterministic and easy to test
excepted(addr) if {
	input.today < exceptions[addr].expires
}

ssh_open(rc) if {
	rc.type == "aws_security_group"
	some rule in rc.change.after.ingress
	rule.from_port <= 22
	rule.to_port >= 22
	"0.0.0.0/0" in rule.cidr_blocks
}

deny contains msg if {
	some rc in input.resource_changes
	ssh_open(rc)
	not excepted(rc.address)
	msg := sprintf("%s: SSH open to 0.0.0.0/0", [rc.address])
}

warn contains msg if {
	some rc in input.resource_changes
	ssh_open(rc)
	excepted(rc.address)
	msg := sprintf("%s: allowed by exception until %s", [rc.address, exceptions[rc.address].expires])
}
